	var sp: Node = _spawner
	if sp == null:
		return false
	var rt: int = int(sp.get_res_type_at(cell))
	if rt < 0:
		return false
	var removed: bool = sp.remove_resource_at(cell)
	var rid: StringName = ResourceIcons.res_type_id(rt)
	if rid != &"":
		GameEventBus.resource_extracted.emit(cell, rid, ResourceIcons.res_type_amount(rt))
	return removed

func _nearest_resource() -> Vector2i:
	# Только узлы, реально собируемые через WorldSpawner (есть маркер).
	var cells: Array = []
	var sp: Node = _spawner
	for c in _map().resource_cells.keys():
		if sp == null or int(sp.get_res_type_at(c)) >= 0:
			cells.append(c)
	return _nearest_cell(cells)

	super._step()

